import React, { useEffect } from 'react';
import {
  Header,
  Button,
  SpaceBetween,
  Box,
  Link,
  Link as CLink,
} from '@cloudscape-design/components';

import stemgenius from './logos/StemGenius.png'
import RepublicPoly from './logos/RP.png'
import SIT_logo from './logos/SIT logo.jpg'

export default function ResumeTemplate({ data = sampleData }) {
  const [showMicrosoft, setShowMicrosoft] = React.useState(true);
  const [showOthers, setShowOthers] = React.useState(false);
  const [showNotableProjects, setShowNotableProjects] = React.useState(true);
  const [printMode, setPrintMode] = React.useState(false);
  const [showEducation, setShowEducation] = React.useState(false);
  const [showProjects, setShowProjects] = React.useState(false);
  const [showVideos, setShowVideos] = React.useState(false);
  const [showBlogs, setShowBlogs] = React.useState(false);
  const [showCertifications, setShowCertifications] = React.useState(false);


  const sortedCertifications = [...data.certifications].sort(
    (a, b) => Number(b.date) - Number(a.date)
  );
  const awsCerts = sortedCertifications.filter(
    (c) => c.provider === 'Amazon Web Services' && c.certification.includes('Certified')
  );
  const awsKnowledge = sortedCertifications.filter(
    (c) => c.provider === 'Amazon Web Services' && c.certification.includes('Knowledge')
  );
  const microsoftLogo = sortedCertifications.filter(
    (c) => c.provider === 'Microsoft' && Number(c.date) >= 2017 && c.logo
  );
  const microsoftAllLogo = sortedCertifications.filter(
    (c) => c.provider === 'Microsoft' && c.logo
  );
  const microsoft = sortedCertifications.filter(
    (c) => c.provider === 'Microsoft' && Number(c.date) >= 2017
  );
  const microsoftAll = sortedCertifications.filter(
    (c) => c.provider === 'Microsoft'
  );
  const others = sortedCertifications.filter(
    (c) => c.provider !== 'Microsoft' && c.provider !== 'Amazon Web Services'
  );
  const othersLogo = sortedCertifications.filter(
    (c) => c.provider !== 'Microsoft' && c.provider !== 'Amazon Web Services' && c.logo
  );
  const othersAll = sortedCertifications.filter(
    (c) => c.provider !== 'Microsoft' && c.provider !== 'Amazon Web Services' && Number(c.date) >= 2017
  );
  const othersLogoAll = sortedCertifications.filter(
    (c) => c.provider !== 'Microsoft' && c.provider !== 'Amazon Web Services' && c.logo && Number(c.date) >= 2017
  );

  useEffect(() => {
    if (sampleData.videos.length === 0) {
      setShowVideos(false);
    }
    else {
      setShowVideos(true);
    }
    if (sampleData.education.length === 0) {
      setShowEducation(false);
    }
    else {
      setShowEducation(true);
    }
    if (sampleData.projects.length === 0) {
      console.log('No projects to show');
      setShowProjects(false);
      setShowNotableProjects(false);
    }
    else {
      setShowProjects(true);
    }
    if (sampleData.certifications.length === 0) {
      setShowCertifications(false);
    }
    else {
      setShowCertifications(true);
    }
    if (sampleData.blogs.length === 0) {
      setShowBlogs(false);
    }
    else {
      setShowBlogs(true);
    }

    if (!printMode) return;

    const id = requestAnimationFrame(() => {
      window.print();
    });

    return () => cancelAnimationFrame(id);
  }, [printMode]);

  // Reset when print dialog closes
  useEffect(() => {
    const afterPrint = () => setPrintMode(false);
    window.addEventListener("afterprint", afterPrint);
    return () => window.removeEventListener("afterprint", afterPrint);
  }, []);

  return (
    <div className="resume-page">
      < div >
        <Header
          variant="h1"
          description={data.title}
        >
          <div>
            <div>
              <div>{data.name}</div>
              <div>{data.role} — {data.location}</div>
            </div>
          </div>
        </Header>
        <div>
          {/* Left column: contact / skills */}
          <aside >
            <Box>
              <SpaceBetween size="s">
                <div>{data.email}</div>
                <div>{data.phone}</div>
                <CLink href={data.website}>{data.website}</CLink>
              </SpaceBetween>
              <br />
            </Box>

            <Box>
              <Header>Summary</Header>
              <br />
              <div >
                {data.summary.map((s) => (
                  <span key={s} >{s}</span>
                ))}
              </div>
              <br />
            </Box>

            <Box>
              <Header>Skills</Header>
              <br />
              <div >
                {data.skills.map((s) => (
                  <div key={s} >• {s}</div>
                ))}
              </div>
              <br />
            </Box>
            <Box>
              <Header>Tech</Header>
              <br />
              <div >
                {data.tech.map((t) => (
                  <div key={t} >• {t}</div>
                ))}
              </div>
              <br />
            </Box>
          </aside>
          {/* Right column: main content */}
          <main>
            <section >
              <Box>
                <Header>Experience</Header>
                <SpaceBetween size="m">
                  <br />
                  <div>
                    {data.experience.map((exp) => (
                      <article key={exp.role} >
                        <SpaceBetween size="s" direction='horizontal'>
                          <div>
                            <img
                              src={exp.logo}
                              alt={exp.company}
                              style={{ width: 60, height: 60, objectFit: 'contain' }}
                            />
                          </div>
                          <div>
                            <div>
                              <div >{exp.role}</div>
                              <div ><strong>{exp.company}</strong> — {exp.period}</div>
                            </div>
                            <div >{exp.location}</div>
                          </div>
                        </SpaceBetween>
                        <br />
                        <div ><strong>{exp.mainStrong}</strong> {exp.main}</div>
                        <ul>
                          {(() => {
                            const maxBullets = printMode
                              ? Math.min(
                                exp.maxBullets ?? exp.responsibilities.length,
                                exp.responsibilities.length
                              )
                              : exp.responsibilities.length;

                            return exp.responsibilities
                              .slice(0, maxBullets)
                              .map((item, i) => (
                                <li key={i}>
                                  <strong>{item.lead}</strong> {item.detail}
                                </li>
                              ));
                          })()}
                        </ul>
                        <br />
                      </article>
                    ))}
                  </div>
                  {!showProjects && !showNotableProjects || printMode ? null : <Button onClick={() => setShowNotableProjects((v) => !v)}>
                    {showNotableProjects ? 'Hide Notable Projects' : 'Show Notable Projects'}
                  </Button>}
                  {printMode ? null : <br />}
                </SpaceBetween>

              </Box>
            </section>
            {!showNotableProjects || printMode ? null : <section >
              <Box>
                <Header>Noteable Projects</Header>
                <SpaceBetween size="m">
                  <br />
                  <div>
                    {data.projects.map((projects) => (
                      <article key={projects.role} >
                        <SpaceBetween size="s" direction='horizontal'>
                          <div>
                            <img
                              src={projects.logo}
                              alt={projects.company}
                              style={{ width: 60, height: 60, objectFit: 'contain' }}
                            />
                          </div>
                          <div>
                            <div>
                              <div >{projects.role}</div>
                              <div ><strong>{projects.company}</strong> — {projects.period}</div>
                            </div>
                            <div >{projects.location}</div>
                          </div>
                        </SpaceBetween>
                        <br />
                        <div ><strong>{projects.mainStrong}</strong> {projects.main}</div>
                        <ul>
                          {(() => {
                            const maxBullets = printMode
                              ? Math.min(
                                projects.maxBullets ?? projects.responsibilities.length,
                                projects.responsibilities.length
                              )
                              : projects.responsibilities.length;

                            return projects.responsibilities
                              .slice(0, maxBullets)
                              .map((item, i) => (
                                <li key={i}>
                                  <strong>{item.lead}</strong> {item.detail}
                                </li>
                              ));
                          })()}
                        </ul>
                        <br />
                      </article>
                    ))}
                  </div>
                </SpaceBetween>
              </Box>
            </section>}
            {showEducation ? <section >
              <Box>
                <Header>Education</Header>
                <SpaceBetween size="m">
                  <br />
                  <div>
                    {data.education.map((edu) => (
                      <article key={edu.degree} >
                        <SpaceBetween size="s" direction='horizontal'>
                          <div>
                            <img
                              src={edu.logo}
                              alt={edu.institution}
                              style={{ width: 60, height: 60, objectFit: 'contain' }}
                            />
                          </div>
                          <div>
                            <div>
                              <div >{edu.degree}</div>
                              <div ><strong>{edu.institution}</strong> — {edu.period}</div>
                            </div>
                            <div >{edu.location}</div>
                          </div>
                        </SpaceBetween>
                        <br />
                        <div ><strong>{edu.mainStrong}</strong> {edu.main}</div>
                        <ul>
                          {(() => {
                            const maxBullets = printMode
                              ? Math.min(
                                edu.maxBullets ?? edu.courses.length,
                                edu.courses.length
                              )
                              : edu.courses.length;

                            return edu.courses
                              .slice(0, maxBullets)
                              .map((item, i) => (
                                <li key={i}>
                                  <strong>{item.Course}</strong> {item.Description}
                                </li>
                              ));
                          })()}
                        </ul>
                        <br />
                      </article>
                    ))}
                  </div>
                  {!showProjects && !showNotableProjects || printMode ? null : <Button onClick={() => setShowNotableProjects((v) => !v)}>
                    {showNotableProjects ? 'Hide Notable Projects' : 'Show Notable Projects'}
                  </Button>}
                  {printMode ? null : <br />}
                </SpaceBetween>

              </Box>
            </section> : null}
            {showVideos ? <section>
              <Box>
                {printMode ? null : <Header>Video Demos</Header>}
                {printMode ? null : <br />}
                {printMode ? null : (
                  <div
                    style={{
                      display: "grid",
                      gap: 24,
                      justifyContent: "center",                 // center the whole grid
                      gridTemplateColumns: "repeat(auto-fit, minmax(320px, 560px))",
                    }}
                  >
                    {sampleData.videos.map((c) => (
                      <div key={c.link} style={{ width: "100%", maxWidth: 560 }}>
                        {/* responsive 16:9 */}
                        <div style={{ position: "relative", width: "100%", paddingTop: "56.25%" }}>
                          <iframe
                            src={c.link}
                            title={c.title}
                            frameBorder="0"
                            allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share"
                            allowFullScreen
                            style={{
                              position: "absolute",
                              inset: 0,
                              width: "100%",
                              height: "100%",
                            }}
                          />
                        </div>
                        <div style={{ marginTop: 8, fontWeight: 600 }}>{c.title}</div>
                      </div>
                    ))}
                  </div>
                )}
              </Box>
              {printMode ? null : <br />}
            </section> : null}
            {showBlogs ? <section>
              <Box>
                {printMode ? null : <Header>Industry Blogs</Header>}
                {printMode ? null : <br />}
                {printMode ? null : (
                  <SpaceBetween size="m" direction="vertical">
                    {sampleData.blogs.map((c) => (
                      <Link key={c.link} href={c.link}>
                        <div
                          style={{
                            display: 'flex',
                            alignItems: 'center',   // 👈 vertical centering
                            gap: '12px'             // space between image and text
                          }}
                        >
                          <img
                            src={c.icon}
                            alt={c.title}
                            style={{ width: 48, height: 48, objectFit: 'contain' }}
                          />
                          <span>{c.title}</span>
                        </div>
                      </Link>
                    ))}
                  </SpaceBetween>
                )}
              </Box>
              {printMode ? null : <br />}
            </section> : null}
            {showCertifications ? <section >
              <Box>
                {printMode ? <Header>Certifications (Sumary)</Header> : <Header>Certifications</Header>}
                {/* AWS badge strip */}
                {printMode ? <div >
                  {data.printCertifications.map((certGroup, i) =>
                    Object.entries(certGroup).map(([provider, certs]) => (
                      <div key={`${provider}-${i}`} style={{ marginBottom: '8px' }}>
                        <strong>{provider}:</strong>{' '}
                        <span>{certs}</span>
                      </div>
                    ))
                  )}
                </div> : <div>
                  {showOthers ? <div >
                    {othersLogo.map((c) => (
                      <img
                        key={c.certification}
                        src={c.logo}
                        alt={c.certification}
                        style={{ width: 80, height: 80, objectFit: 'contain' }}
                      />
                    ))}
                  </div> : <div >
                    {othersLogoAll.map((c) => (
                      <img
                        key={c.certification}
                        src={c.logo}
                        alt={c.certification}
                        style={{ width: 80, height: 80, objectFit: 'contain' }}
                      />
                    ))}
                  </div>}
                  {printMode ? null : <div><Button onClick={() => setShowOthers((v) => !v)}>
                    {showOthers ? 'Show Recent Certifications' : 'Show All Certifications'}
                  </Button><br /></div>}
                  <br />
                  {showOthers ? <div >
                    {others.map((c) => (
                      <div key={c.certification}>
                        <span >{c.certification}</span>
                        <span > • {c.date}</span>
                      </div>
                    ))}
                  </div> : <div >
                    {othersAll.map((c) => (
                      <div key={c.certification}>
                        <span >{c.certification}</span>
                        <span > • {c.date}</span>
                      </div>
                    ))}
                  </div>}</div>}
              </Box>
            </section> : null}
          </main>
        </div>
        <br />
        {/* Footer actions */}
        <div >
          {printMode ? null : (
            <Button onClick={() => setPrintMode(true)}>
              Print / Save as PDF
            </Button>
          )}
        </div>
      </div >
    </div>
  );
}

